"""Check versioned names through an explicit, reviewable compatibility list.

Protocol/schema and frozen-run identifiers are business contracts, not generic
permission to use revision suffixes. Every retained occurrence therefore has
to identify its exact path, symbol, rationale, and removal phase here.
"""

from __future__ import annotations

import re
from pathlib import Path


VERSIONED_NAME = re.compile(r"\b[A-Za-z_][A-Za-z0-9_]*_v[0-9]+\b")


def _entry(path: str, symbol: str, why: str, removal_phase: str) -> dict:
    return {
        "path": path,
        "symbol": symbol,
        "why_allowed": why,
        "removal_phase": removal_phase,
    }


