def _allowlist_by_key():
    result = {}
    for entry in ALLOWLIST:
        key = (entry["path"], entry["symbol"])
        if key in result:
            raise AssertionError("duplicate versioned-name allowlist entry: {}".format(key))
        if not entry["why_allowed"] or not entry["removal_phase"]:
            raise AssertionError("incomplete versioned-name allowlist entry: {}".format(key))
        result[key] = entry
    return result


def main() -> int:
    root = Path(__file__).resolve().parents[2]
    allowlist = _allowlist_by_key()
    files = []
    for directory in ("python", "scripts", "config"):
        files.extend((root / directory).rglob("*.py"))
        files.extend((root / directory).rglob("*.sh"))
    files.append(root / "tests" / "benchmark_hotpaths.py")

    violations = []
    observed = set()
    for path in sorted(files):
        text = path.read_text(encoding="utf-8")
        relative_path = path.relative_to(root).as_posix()
        for match in VERSIONED_NAME.finditer(text):
            symbol = match.group(0)
            key = (relative_path, symbol)
            observed.add(key)
            if key in allowlist:
                continue
            line = text.count("\n", 0, match.start()) + 1
            violations.append(
                "{}:{}:{}".format(relative_path, line, symbol)
            )
    unexplained = sorted(observed.difference(allowlist))
    if violations or unexplained:
        raise AssertionError(
            "unexplained versioned business names: {}".format(
                "; ".join(violations)
            )
        )
    print("SEMANTIC_CONTRACT_NAMING=PASS")
    print("VERSIONED_NAME_ALLOWLIST_ENTRIES={}".format(len(allowlist)))
    print("UNEXPLAINED_VERSIONED_BUSINESS_NAME_COUNT=0")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
